// PreToolUse hook (Edit|Write): keeps Claude from hand-editing generated code.
//
// - proto-gen/ is rebuilt from the .proto files on every `npm start`/`npm run build`,
//   so a manual edit there is always lost - the change belongs in the .proto file instead.
// - Migrations/ are generated by `dotnet ef`, but hand-editing one is occasionally legitimate
//   (e.g. a data migration), so that case asks the user instead of refusing outright.
import { readFileSync } from 'node:fs';

const input = JSON.parse(readFileSync(0, 'utf8'));
// Normalize Windows backslashes so one pattern matches on every OS.
const filePath = (input.tool_input?.file_path ?? '').replaceAll('\\', '/');

function decide(permissionDecision, permissionDecisionReason) {
  console.log(JSON.stringify({
    hookSpecificOutput: { hookEventName: 'PreToolUse', permissionDecision, permissionDecisionReason }
  }));
  process.exit(0);
}

if (filePath.includes('/src/app/core/proto-gen/')) {
  decide('deny', 'proto-gen/ is generated by `npm run proto:gen`. Change the .proto file in src/TaskBoard.Contracts/Protos instead.');
}

if (filePath.includes('/Persistence/Migrations/')) {
  decide('ask', 'Migrations are generated by `dotnet ef migrations add`. Hand-edit only for a deliberate data migration.');
}
